from pathlib import Path
import json,shutil
root=Path(__file__).resolve().parent.parent
paths=json.loads((root/'data/academy_paths.json').read_text())
meta=[]
for p in paths:
 full=json.dumps(p,ensure_ascii=False,separators=(',',':'))
 p['offline_bundle_size_kb']=round(len(full.encode())/1024,1)
 out=root/'dist/data/paths';out.mkdir(exist_ok=True)
 (out/(p['id']+'.json')).write_text(json.dumps(p,ensure_ascii=False,separators=(',',':')))
 m={k:v for k,v in p.items() if k!='stages'};m['stages']=[]
 for stage in p['stages']:
  st={k:v for k,v in stage.items() if k!='steps'};st['steps']=[]
  for step in stage['steps']:
   d=root/'dist/data/steps'/p['id'];d.mkdir(exist_ok=True,parents=True)
   (d/(step['id']+'.json')).write_text(json.dumps(step,ensure_ascii=False,separators=(',',':')))
   st['steps'].append({k:v for k,v in step.items() if k in ['id','type','title_fr','minutes','offline','required']})
  m['stages'].append(st)
 meta.append(m)
(root/'dist/data/paths/index.json').write_text(json.dumps(meta,ensure_ascii=False,separators=(',',':')))
for f in ['katex.min.js','katex.min.css']:
 d=root/'dist/vendor';d.mkdir(exist_ok=True);shutil.copy(root/'node_modules/katex/dist'/f,d/f)
shutil.copytree(root/'node_modules/katex/dist/fonts',root/'dist/vendor/fonts',dirs_exist_ok=True)
